export const LANGUAGE_STORAGE_KEY = 'farmdirect:language'

export const languageNames = { en: 'English', hi: 'हिन्दी', te: 'తెలుగు', ta: 'தமிழ்', ml: 'മലയാളം', kn: 'ಕನ್ನಡ', mr: 'मराठी', bn: 'বাংলা' }

export const SELECTABLE_LANGUAGES = ['en', 'hi', 'te', 'ta', 'kn', 'ml', 'mr', 'bn']

export function getStoredLanguage() {
  try {
    const value = localStorage.getItem(LANGUAGE_STORAGE_KEY)
    return SELECTABLE_LANGUAGES.includes(value) ? value : null
  } catch {
    return null
  }
}

export function storeLanguage(code) {
  if (!SELECTABLE_LANGUAGES.includes(code)) return
  try { localStorage.setItem(LANGUAGE_STORAGE_KEY, code) } catch { /* storage unavailable */ }
}

